#' Build a local BLAST reference database from a BOLD BCDM TSV
#'
#' @param bcdm_path Character. Path to the BCDM TSV file generated by [bold_retrieve()].
#' @param db_dir Character. Directory to save the formatted FASTA and BLAST database files.
#' @param db_name Character. Base name for the output BLAST database files. Default is `"bold_ref_db"`.
#'
#' @return Invisibly returns the base path to the compiled BLAST database (`file.path(db_dir, db_name)`).
#' @export
bcdm2blastdb <- function(bcdm_path, db_dir, db_name = "bold_ref_db") {
    
    message("1/3: Reading BCDM data...")
    # Read the TSV
    df <- read.delim(bcdm_path, sep = "\t", header = TRUE, stringsAsFactors = FALSE)
    
    # Filter out records that lack nucleotide sequences
    has_seq <- !is.na(df$nuc) & trimws(df$nuc) != ""
    df_seq <- df[has_seq, ]
    
    if (nrow(df_seq) == 0) {
        stop("No nucleotide sequences found in the provided BCDM file.")
    }
    
    message(sprintf("2/3: Formatting %s sequences into FASTA...", nrow(df_seq)))
    
    # Clean up empty or NA fields for the header
    safe_replace <- function(x, replacement) {
        ifelse(is.na(x) | trimws(x) == "", replacement, gsub(" ", "_", trimws(x)))
    }
    
    # Build FASTA headers: >processid|BIN|species
    headers <- sprintf(">%s|%s|%s", 
                       safe_replace(df_seq$processid, "NO_ID"), 
                       safe_replace(df_seq$bin_uri, "NO_BIN"), 
                       safe_replace(df_seq$species, "sp."))
    
    # Interleave headers and sequences
    fasta_lines <- c(rbind(headers, df_seq$nuc))
    
    # Ensure directory exists and write FASTA
    if (!dir.exists(db_dir)) dir.create(db_dir, recursive = TRUE)
    fasta_path <- file.path(db_dir, paste0(db_name, ".fasta"))
    
    writeLines(fasta_lines, fasta_path)
    
    message("3/3: Executing NCBI makeblastdb...")
    # Construct arguments for makeblastdb
    db_out_path <- file.path(db_dir, db_name)
    cmd_args <- c("-in", fasta_path, 
                  "-dbtype", "nucl", 
                  "-title", db_name,
                  "-out", db_out_path)
    
    # Execute system call
    status <- tryCatch({
        system2("makeblastdb", args = cmd_args, stdout = TRUE, stderr = TRUE)
    }, warning = function(w) {
        stop("makeblastdb failed. Ensure NCBI BLAST+ is installed and added to your system PATH.")
    })
    
    # Print the system output
    cat(status, sep = "\n")
    message(sprintf("\nSuccess: BLAST database '%s' compiled at %s", db_name, db_dir))
    
    return(invisible(db_out_path))
}

#' Run a local BLAST search against a custom database
#'
#' @param query Character. Path to a query FASTA file, or a raw DNA sequence string.
#' @param db_path Character. Path to the BLAST database (the base name returned by [bcdm2blastdb()]).
#' @param evalue Numeric. Expectation value (`E`) threshold for saving hits. Default is `1e-5`.
#' @param max_target_seqs Integer. Maximum number of aligned sequences to keep per query. Default is `10`.
#'
#' @return A `data.frame` of BLAST tabular hits (format 6), or `NULL` if no hits are found.
#' @export
blast <- function(query, db_path, evalue = 1e-5, max_target_seqs = 10) {
    
    # 1. Handle query input (file vs raw sequence)
    if (file.exists(query)) {
        query_file <- query
    } else {
        # Assume it's a raw sequence, write to a temporary FASTA
        query_file <- tempfile(fileext = ".fasta")
        writeLines(c(">query_seq", query), query_file)
        on.exit(unlink(query_file), add = TRUE)
    }
    
    # 2. Setup temporary output file
    out_file <- tempfile(fileext = ".tsv")
    on.exit(unlink(out_file), add = TRUE)
    
    message("Executing NCBI blastn...")
    
    # 3. Construct blastn arguments
    cmd_args <- c(
        "-query", query_file,
        "-db", db_path,
        "-out", out_file,
        "-evalue", as.character(evalue),
        "-max_target_seqs", as.character(max_target_seqs),
        "-outfmt", shQuote("6 qseqid sseqid pident length mismatch gapopen qstart qend sstart send evalue bitscore")
    )
    
    # 4. Execute system call and capture output
    # Suppress warnings temporarily so we can handle the error status manually
    output <- suppressWarnings(system2("blastn", args = cmd_args, stdout = TRUE, stderr = TRUE))
    status_code <- attr(output, "status")
    
    # If system2 returns a status attribute > 0, the command failed
    if (!is.null(status_code) && status_code != 0) {
        error_msg <- paste(output, collapse = "\n")
        stop(sprintf("NCBI BLAST+ failed with exit status %s.\nDetails:\n%s", status_code, error_msg))
    }
    
    # 5. Read and return the output
    if (file.info(out_file)$size > 0) {
        cnames <- c("qseqid", "sseqid", "pident", "length", "mismatch", "gapopen", 
                    "qstart", "qend", "sstart", "send", "evalue", "bitscore")
        res <- read.table(out_file, sep = "\t", header = FALSE, stringsAsFactors = FALSE, col.names = cnames)
        message(sprintf("BLAST complete. Found %s hits.", nrow(res)))
        return(res)
    } else {
        message("BLAST complete. No hits found.")
        return(NULL)
    }
}